DROP TABLE IF EXISTS `fixed_assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fixed_assets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `counts` int NOT NULL,
  `amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `depreciation_duration` int NOT NULL,
  `start_date` int NOT NULL,
  `end_date` int NOT NULL,
  `payment_terms` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `custom_collection_policy` json DEFAULT NULL,
  `from_total_or_executions` json DEFAULT NULL,
  `admin_depreciation_percentage` decimal(14,2) NOT NULL DEFAULT '0.00',
  `manufacturing_depreciation_percentage` decimal(14,2) NOT NULL DEFAULT '0.00',
  `equity_funding_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `interest_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `tenor` int NOT NULL,
  `installment_interval` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` bigint unsigned NOT NULL,
  `product_allocations` json DEFAULT NULL,
  `monthly_product_allocations` json DEFAULT NULL,
  `is_as_revenue_percentages` bigint unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `replacement_cost_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `replacement_cost_interval` int NOT NULL DEFAULT '0',
  `grace_period` int DEFAULT '0',
  `depreciation_statement` json DEFAULT NULL,
  `capitalization_statement` json DEFAULT NULL,
  `admin_depreciations` json DEFAULT NULL,
  `ffe_equity_payment` json DEFAULT NULL,
  `ffe_loan_withdrawal` json DEFAULT NULL,
  `income_statement_loan_capitalized_interests` json DEFAULT NULL,
  `loan_capitalized_interests` json DEFAULT NULL,
  `ffe_loan_withdrawal_end_balance` json DEFAULT NULL,
  `ffe_payment` json DEFAULT NULL,
  `statement` json DEFAULT NULL,
  `ffe_execution_and_payment` json DEFAULT NULL,
  `ffe_payable` json DEFAULT NULL,
  `reservation_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `contractual_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `after_months` int NOT NULL DEFAULT '0',
  `installment_grace_period` decimal(14,2) NOT NULL DEFAULT '0.00',
  `installment_count` int NOT NULL DEFAULT '0',
  `payment_installment_interval` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fixed_assets_project_id_foreign` (`project_id`),
  CONSTRAINT `fixed_assets_project_id_foreign` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
