--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `collection_policy_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `collection_policy_value` json DEFAULT NULL,
  `collection_statement` json DEFAULT NULL,
  `export_collection_statement` json DEFAULT NULL,
  `local_collection_statement` json DEFAULT NULL,
  `collection_policy_interval` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `selling_start_date` int NOT NULL DEFAULT '0',
  `max_capacity` json DEFAULT NULL,
  `target_percentages` json DEFAULT NULL,
  `target_quantities` json DEFAULT NULL,
  `local_target_quantities` json DEFAULT NULL,
  `local_growth_rates` json DEFAULT NULL,
  `local_price_per_unit` json DEFAULT NULL,
  `sensitivity_price_rate` decimal(14,2) DEFAULT NULL,
  `sales_target_values` json DEFAULT NULL,
  `fg_inventory_value` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fg_beginning_inventory_breakdowns` json DEFAULT NULL,
  `product_inventory_value_statement` json DEFAULT NULL,
  `product_overheads_statement` json DEFAULT NULL,
  `raw_material_statement` json DEFAULT NULL,
  `product_overheads_allocation` json DEFAULT NULL,
  `product_depreciation_allocation` json DEFAULT NULL,
