  `manpower_is_as_revenue_percentages` json DEFAULT NULL,
  `salaries_annual_increase` decimal(14,2) NOT NULL DEFAULT '0.00',
  `salaries_tax_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `social_insurance_rate` decimal(14,2) NOT NULL DEFAULT '0.00',
  `comment_for_raw_materials` longtext COLLATE utf8mb4_unicode_ci,
  `vat_statements` json DEFAULT NULL,
  `corporate_taxes_statement` json DEFAULT NULL,
  `intro_paragraph` longtext COLLATE utf8mb4_unicode_ci,
