  `rm_inventory_coverage_days` int NOT NULL,
  `measurement_unit` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `vat_rate` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `withhold_tax_rate` decimal(14,4) NOT NULL DEFAULT '0.0000',
  `inventory_value_statement` json DEFAULT NULL,
  PRIMARY KEY (`id`),
